return [
  {
    json: {
      sourceFile: "manual-demo-shipment.txt",
      documentText: `
Shipment reference: SHIP-DEMO-001
Customer PO: PO-DEMO-001
Customer: Admetec Demo Customer

Line 1:
Product code: ADM-DEMO-001
Description: Demo shipment extraction line
Quantity: 2
Serial number: SN-DEMO-001
`
    }
  }
];

const CFG = {
  workers: Number(process.env.AGENTICS_LLM_WORKERS_NORMAL || 4),
  maxTokens: Number(process.env.AGENTICS_LLM_MAX_TOKENS_NORMAL || 1024),
  model: process.env.AGENTICS_DMR_MODEL || "docker.io/ai/qwen2.5:latest",
  dmrUrl: process.env.AGENTICS_DMR_URL || "http://host.docker.internal:12434/engines/llama.cpp/v1/chat/completions",
  graphqlUrl: process.env.AGENTICS_GRAPHQL_URL || "http://host.docker.internal:5000/graphql",
  tikaUrl: process.env.AGENTICS_TIKA_URL || "http://tika:9998/tika",
  wahaUrl: process.env.AGENTICS_WAHA_URL || "http://waha:3000/api/sendText",
  wahaApiKey: process.env.AGENTICS_WAHA_API_KEY || "change-this-waha-api-key",
  wahaSession: process.env.AGENTICS_WAHA_SESSION || "default",
  wahaChatId: process.env.AGENTICS_WAHA_CHAT_ID || "31613717081@c.us"
};

if (typeof fetch !== "function") {
  throw new Error("Global fetch is not available in this n8n Code node runtime.");
}

const helpers = this.helpers;

async function postJson(url, body, headers = {}) {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...headers },
    body: JSON.stringify(body)
  });

  const text = await res.text();
  let json;
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    throw new Error(`HTTP ${res.status} from ${url}: non-JSON response: ${text.slice(0, 800)}`);
  }

  if (!res.ok) {
    throw new Error(`HTTP ${res.status} from ${url}: ${JSON.stringify(json).slice(0, 1200)}`);
  }

  return json;
}

async function putToTika(buffer) {
  const res = await fetch(CFG.tikaUrl, {
    method: "PUT",
    headers: { "Accept": "text/plain" },
    body: buffer
  });

  const text = await res.text();

  if (!res.ok) {
    throw new Error(`Tika HTTP ${res.status}: ${text.slice(0, 800)}`);
  }

  return text;
}

async function gql(query, variables = {}) {
  const result = await postJson(CFG.graphqlUrl, { query, variables });
  if (result.errors) {
    throw new Error("GraphQL errors: " + JSON.stringify(result.errors));
  }
  return result.data;
}

function namedType(type) {
  let t = type;
  while (t && t.ofType) t = t.ofType;
  return t ? t.name : null;
}

const typeCache = new Map();

async function getInputFields(typeName) {
  if (typeCache.has(typeName)) return typeCache.get(typeName);

  const data = await gql(
    `query($name: String!) {
      __type(name: $name) {
        name
        inputFields {
          name
          type {
            kind
            name
            ofType {
              kind
              name
              ofType {
                kind
                name
                ofType {
                  kind
                  name
                  ofType {
                    kind
                    name
                  }
                }
              }
            }
          }
        }
      }
    }`,
    { name: typeName }
  );

  const fields = data.__type?.inputFields || [];
  typeCache.set(typeName, fields);
  return fields;
}

let mutationCache = null;

async function getMutations() {
  if (mutationCache) return mutationCache;

  const data = await gql(
    `query {
      __schema {
        mutationType {
          fields {
            name
            args {
              name
              type {
                kind
                name
                ofType {
                  kind
                  name
                  ofType {
                    kind
                    name
                    ofType {
                      kind
                      name
                      ofType {
                        kind
                        name
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }`
  );

  mutationCache = data.__schema?.mutationType?.fields || [];
  return mutationCache;
}

function lowerFirst(value) {
  return value.charAt(0).toLowerCase() + value.slice(1);
}

async function getCreateSpec(entityName) {
  const mutations = await getMutations();
  const wanted = `create${entityName}`;

  const mutation =
    mutations.find(m => m.name === wanted) ||
    mutations.find(m => m.name.toLowerCase() === wanted.toLowerCase());

  if (!mutation) {
    throw new Error(`Could not find PostGraphile mutation ${wanted}`);
  }

  const inputArg = mutation.args.find(a => a.name === "input") || mutation.args[0];
  const outerInputType = namedType(inputArg.type);
  const outerFields = await getInputFields(outerInputType);

  const payloadField = lowerFirst(entityName);

  const rowField =
    outerFields.find(f => f.name.toLowerCase() === payloadField.toLowerCase()) ||
    outerFields.find(f => f.name !== "clientMutationId");

  if (!rowField) {
    throw new Error(`Could not find row input field for ${mutation.name}`);
  }

  const rowInputType = namedType(rowField.type);
  const rowFields = await getInputFields(rowInputType);

  return {
    mutationName: mutation.name,
    outerInputType,
    rowFieldName: rowField.name,
    rowFields,
    payloadField
  };
}

function getCaseInsensitive(obj, key) {
  if (!obj || typeof obj !== "object") return undefined;
  const found = Object.keys(obj).find(k => k.toLowerCase() === key.toLowerCase());
  return found ? obj[found] : undefined;
}

function coerceForField(value, field) {
  if (value === undefined || value === null) return undefined;

  const typeName = namedType(field.type);
  if (typeName === "Int") {
    const n = parseInt(String(value).replace(",", "."), 10);
    return Number.isFinite(n) ? n : undefined;
  }

  if (["Float", "BigFloat", "Decimal"].includes(typeName)) {
    const n = Number(String(value).replace(",", "."));
    return Number.isFinite(n) ? n : value;
  }

  return value;
}

function buildDocumentInput(rowFields, extracted, sourceFile, text) {
  const doc = extracted.document || {};
  const firstLine = (extracted.lines || [])[0] || {};
  const out = {};

  for (const field of rowFields) {
    const name = field.name;
    if (["id", "createdAt", "updatedAt"].includes(name)) continue;

    let value = getCaseInsensitive(doc, name) ?? getCaseInsensitive(extracted, name);

    if (value === undefined) {
      const n = name.toLowerCase();

      if (n.includes("source") || n.includes("file")) value = sourceFile;
      else if (n === "documenttype" || n.includes("type")) value = doc.documentType || "shipment";
      else if (n.includes("shipment") && n.includes("ref")) value = doc.shipmentRef || firstLine.shipmentRef || "UNKNOWN";
      else if (n.includes("customer") && n.includes("po")) value = doc.customerPo || firstLine.customerPo || "";
      else if (n.includes("customer") && n.includes("name")) value = doc.customerName || "";
      else if (n.includes("invoice")) value = doc.invoiceNumber || "";
      else if (n.includes("date")) value = doc.shipmentDate || doc.invoiceDate || undefined;
      else if (n === "rawText" || n === "documentText") value = text;
    }

    value = coerceForField(value, field);
    if (value !== undefined && value !== null && value !== "") out[name] = value;
  }

  return out;
}

function buildLineInput(rowFields, line, doc, documentId) {
  const out = {};

  for (const field of rowFields) {
    const name = field.name;
    if (["id", "createdAt", "updatedAt"].includes(name)) continue;

    let value = getCaseInsensitive(line, name);

    if (value === undefined) {
      const n = name.toLowerCase();

      if (n === "documentid") value = documentId;
      else if (n.includes("product") && n.includes("code")) value = line.productCode || line.itemCode || line.sku || "UNKNOWN";
      else if (n.includes("description")) value = line.productDescription || line.description || "Shipment line";
      else if (n.includes("quantity") || n === "qty") value = line.quantity || "1";
      else if (n.includes("serial")) value = line.serialNumber || line.serial || "";
      else if (n.includes("shipment") && n.includes("ref")) value = line.shipmentRef || doc.shipmentRef || "";
      else if (n.includes("customer") && n.includes("po")) value = line.customerPo || doc.customerPo || "";
      else if (n.includes("unit") && n.includes("price")) value = line.unitPrice;
      else if (n.includes("discount")) value = line.discount;
      else if (n.includes("total")) value = line.lineTotal || line.total;
    }

    value = coerceForField(value, field);
    if (value !== undefined && value !== null && value !== "") out[name] = value;
  }

  return out;
}

async function insertRow(spec, row) {
  const mutation = `
    mutation($input: ${spec.outerInputType}!) {
      ${spec.mutationName}(input: $input) {
        ${spec.payloadField} {
          id
        }
      }
    }
  `;

  const variables = {
    input: {
      [spec.rowFieldName]: row
    }
  };

  const data = await gql(mutation, variables);
  const inserted = data?.[spec.mutationName]?.[spec.payloadField];

  if (!inserted?.id) {
    throw new Error(`Insert did not return id for ${spec.mutationName}: ` + JSON.stringify(data));
  }

  return inserted.id;
}

function extractJsonFromText(text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1);

  if (!candidate || !candidate.trim().startsWith("{")) {
    throw new Error("LLM did not return a JSON object. Raw output: " + text.slice(0, 1200));
  }

  return JSON.parse(candidate);
}

async function extractWithLlm(sourceFile, text) {
  const prompt = `
Extract shipment data from this document.

Return ONLY valid JSON with this shape:
{
  "document": {
    "sourceFile": "string",
    "documentType": "shipment",
    "shipmentRef": "string",
    "customerPo": "string",
    "customerName": "string",
    "invoiceNumber": "string",
    "shipmentDate": "string"
  },
  "lines": [
    {
      "productCode": "string",
      "productDescription": "string",
      "quantity": "string",
      "serialNumber": "string",
      "shipmentRef": "string",
      "customerPo": "string",
      "unitPrice": "string",
      "discount": "string",
      "lineTotal": "string"
    }
  ]
}

Rules:
- Return JSON only.
- Do not include markdown.
- If a value is missing, use an empty string.
- Keep quantities as strings.
- Use the document-level shipmentRef and customerPo on each line when possible.

Source file: ${sourceFile}

Document text:
${text.slice(0, 30000)}
`;

  const response = await postJson(CFG.dmrUrl, {
    model: CFG.model,
    messages: [
      { role: "system", content: "You extract structured shipment data. You only return valid JSON." },
      { role: "user", content: prompt }
    ],
    max_tokens: CFG.maxTokens,
    temperature: 0,
    stream: false
  });

  const content = response?.choices?.[0]?.message?.content || "";
  const extracted = extractJsonFromText(content);

  if (!Array.isArray(extracted.lines) || extracted.lines.length === 0) {
    throw new Error("No shipment lines extracted. LLM JSON: " + JSON.stringify(extracted));
  }

  return extracted;
}

async function getTextForItem(item, index) {
  const json = item.json || {};
  let text = json.documentText || json.text || json.rawText || "";
  let sourceFile = json.sourceFile || json.fileName || json.filename || `n8n-item-${index + 1}`;

  if (!text && item.binary && Object.keys(item.binary).length > 0) {
    const binaryKey = Object.keys(item.binary)[0];
    sourceFile = item.binary[binaryKey]?.fileName || sourceFile;
    const buffer = await helpers.getBinaryDataBuffer(index, binaryKey);
    text = await putToTika(buffer);
  }

  if (!text || !String(text).trim()) {
    throw new Error("No documentText/text/rawText or binary PDF was provided.");
  }

  return { sourceFile, text: String(text) };
}

async function processOne(item, index) {
  const { sourceFile, text } = await getTextForItem(item, index);

  const extracted = await extractWithLlm(sourceFile, text);
  extracted.document = extracted.document || {};
  extracted.document.sourceFile = extracted.document.sourceFile || sourceFile;

  const docSpec = await getCreateSpec("ShipmentDocument");
  const lineSpec = await getCreateSpec("ShipmentLine");

  const documentInput = buildDocumentInput(docSpec.rowFields, extracted, sourceFile, text);
  const documentId = await insertRow(docSpec, documentInput);

  const lineIds = [];
  for (const line of extracted.lines) {
    const lineInput = buildLineInput(lineSpec.rowFields, line, extracted.document, documentId);
    const lineId = await insertRow(lineSpec, lineInput);
    lineIds.push(lineId);
  }

  const readCheck = await gql(
    `query {
      allShipmentLines(first: 10, orderBy: ID_DESC) {
        nodes {
          id
          documentId
          productCode
          productDescription
          quantity
          serialNumber
          shipmentRef
          customerPo
        }
      }
    }`
  );

  const firstLine = extracted.lines[0] || {};
  const message =
    `Shipment extraction OK\n` +
    `Source: ${sourceFile}\n` +
    `Document ID: ${documentId}\n` +
    `Lines inserted: ${lineIds.length}\n` +
    `First product: ${firstLine.productCode || ""}\n` +
    `First serial: ${firstLine.serialNumber || ""}`;

  await postJson(
    CFG.wahaUrl,
    {
      session: CFG.wahaSession,
      chatId: CFG.wahaChatId,
      text: message
    },
    { "X-Api-Key": CFG.wahaApiKey }
  );

  return {
    json: {
      ok: true,
      sourceFile,
      documentId,
      lineIds,
      insertedLines: lineIds.length,
      extracted,
      readCheck: readCheck.allShipmentLines.nodes,
      message
    },
    pairedItem: { item: index }
  };
}

const items = $input.all();
const outputs = [];

for (let start = 0; start < items.length; start += CFG.workers) {
  const chunk = items.slice(start, start + CFG.workers);
  const results = await Promise.all(
    chunk.map((item, offset) =>
      processOne(item, start + offset).catch(error => ({
        json: {
          ok: false,
          sourceFile: item.json?.sourceFile || item.json?.fileName || `item-${start + offset + 1}`,
          error: error.message,
          stack: error.stack
        },
        pairedItem: { item: start + offset }
      }))
    )
  );
  outputs.push(...results);
}

const failed = outputs.filter(o => o.json.ok === false);
if (failed.length > 0) {
  throw new Error("Shipment workflow failed: " + JSON.stringify(failed.map(f => f.json), null, 2));
}

return outputs;
